<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Generator Pro','description'=>'Generate multiple strong random passwords instantly in your browser.','url'=>'https://smarttoolz.in/tools/password-generator-pro/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PASSWORD GENERATOR</span><h1>Password Generator Pro</h1><p>Generate multiple strong passwords quickly with browser randomness.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Length<input id="n" type="number" min="6" max="64" value="16"></label><button id="go" class="tool-btn">Generate Passwords</button><textarea id="out" rows="10" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy All</button></div></section></main><script>(()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*',n=document.getElementById('n'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let a=[];for(let j=0;j<10;j++){let r=new Uint32Array(+n.value||16);crypto.getRandomValues(r);a.push([...r].map(x=>chars[x%chars.length]).join(''))}o.value=a.join('\n')};document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value);document.getElementById('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>